import { readFile } from "node:fs/promises";
import path from "node:path";
import { UPLOAD_DIR, contentTypeFor } from "@/lib/media";

// Serves uploaded listing images. Names are generated by saveImage, so only that pattern is allowed.
export async function GET(_req: Request, { params }: { params: { name: string } }) {
  const m = /^[a-z0-9]+-[a-f0-9]{12}\.(jpg|png|webp)$/.exec(params.name);
  if (!m) return new Response("Not found", { status: 404 });
  try {
    const data = await readFile(path.join(UPLOAD_DIR, params.name));
    return new Response(data, {
      headers: {
        "Content-Type": contentTypeFor(m[1]),
        "Cache-Control": "public, max-age=31536000, immutable",
        "X-Content-Type-Options": "nosniff",
      },
    });
  } catch {
    return new Response("Not found", { status: 404 });
  }
}
